import { spawn as cbmSpawn } from 'node:child_process';

// codebase-memory-mcp:start
// Generated by codebase-memory-mcp for OpenCode.
// Regenerated on install/update from the MCP tool registry, so it cannot
// drift from the tools the server actually serves. Edits inside this block
// are overwritten; edit outside it, or remove the markers to take ownership.
// OpenCode already reaches every tool over MCP; this module adds the
// context surfaces other clients get through hook configuration: graph
// lookup after grep/glob, index-coverage notes after read, session-start
// tier routing (carried on the first tool result of each session, since
// OpenCode documents no context-output lifecycle hook), and reinjection
// after compaction via the documented experimental surface.
import { spawn } from 'node:child_process';

const BIN = '/home/keefer/.local/bin/codebase-memory-mcp';

function augment(payload) {
  return new Promise((resolve) => {
    const child = spawn(BIN, ['hook-augment'], {
      stdio: ['pipe', 'pipe', 'ignore'],
      env: { ...process.env, CBM_LOG_LEVEL: 'error' },
    });
    let out = '';
    child.stdout.on('data', (d) => (out += d.toString()));
    child.on('error', () => resolve(''));
    child.on('close', () => {
      try {
        const ctx = JSON.parse(out)?.hookSpecificOutput?.additionalContext;
        resolve(typeof ctx === 'string' ? ctx : '');
      } catch { resolve(''); }
    });
    child.stdin.end(JSON.stringify(payload));
  });
}

export const CodebaseMemory = async (ctx) => {
  const dir = ctx?.directory;
  const seen = new Set();
  const lifecycle = () =>
    augment({ hook_event_name: 'SessionStart', cwd: dir });
  return {
    'tool.execute.after': async (input, output) => {
      if (typeof output?.output !== 'string') return;
      const pieces = [];
      const sid = input?.sessionID;
      if (typeof sid === 'string' && !seen.has(sid)) {
        seen.add(sid);
        pieces.push(await lifecycle());
      }
      const args = input?.args ?? {};
      const search =
        input?.tool === 'grep' ? 'Grep' : input?.tool === 'glob' ? 'Glob' : null;
      if (search) {
        pieces.push(await augment({
          hook_event_name: 'PreToolUse',
          tool_name: search,
          tool_input: args,
          cwd: dir,
        }));
      } else if (input?.tool === 'read') {
        const filePath = args.filePath ?? args.file_path ?? args.path;
        if (typeof filePath === 'string' && filePath) {
          pieces.push(await augment({
            hook_event_name: 'PostToolUse',
            tool_name: 'Read',
            tool_input: { file_path: filePath },
            cwd: dir,
          }));
        }
      }
      const extra = pieces.filter(Boolean).join('\n');
      if (extra) {
        output.output += '\n' + extra;
      }
    },
    // Documented (experimental) compaction surface: output.context is the
    // mutable array of context strings for the rebuilt session.
    'experimental.session.compacting': async (_input, output) => {
      const note = await lifecycle();
      if (note && Array.isArray(output?.context)) {
        output.context.push(note);
      }
    },
  };
};
// codebase-memory-mcp:end

// ---------------------------------------------------------------------------
// OpenCode V2 entrypoint (kept OUTSIDE the generated marker block above).
//
// The generated block is V1-shaped (named export + hook map). OpenCode V2's
// loader only validates the module's DEFAULT export: { id, setup | effect }.
// On V2 the module therefore failed with:
//   PluginModule.LoadError: Plugin must export a default definition with an id
//   and an effect or setup function. (cause: SchemaError(Missing key ["default"]))
//
// This registers the equivalent hooks through the V2 context. Every
// module-level identifier here is cbm-prefixed so it coexists with the V1
// block, which `codebase-memory-mcp install` refreshes in place, and survives
// a re-append without a "has already been declared" collision.
// ---------------------------------------------------------------------------
const CBM_V2_BIN = '/home/keefer/.local/bin/codebase-memory-mcp';

function cbmAugmentV2(payload) {
  return new Promise((resolve) => {
    const child = cbmSpawn(CBM_V2_BIN, ['hook-augment'], {
      stdio: ['pipe', 'pipe', 'ignore'],
      env: { ...process.env, CBM_LOG_LEVEL: 'error' },
    });
    let out = '';
    child.stdout.on('data', (d) => (out += d.toString()));
    child.on('error', () => resolve(''));
    child.on('close', () => {
      try {
        const ctx = JSON.parse(out)?.hookSpecificOutput?.additionalContext;
        resolve(typeof ctx === 'string' ? ctx : '');
      } catch { resolve(''); }
    });
    child.stdin.end(JSON.stringify(payload));
  });
}

export default {
  id: 'codebase-memory-augment',
  async setup(ctx) {
    const dir = ctx?.location?.directory;
    const seenSessions = new Set();
    let sawLifecycle = false;
    const lifecycle = () =>
      cbmAugmentV2({ hook_event_name: 'SessionStart', cwd: dir });

    await ctx.tool.hook('execute.after', async (event) => {
      if (event?.status && event.status !== 'completed') return;
      const result = event?.result;
      if (!result || typeof result !== 'object') return;

      const pieces = [];
      const sid = event?.sessionID;
      const first = typeof sid === 'string' ? !seenSessions.has(sid) : !sawLifecycle;
      if (first) {
        if (typeof sid === 'string') seenSessions.add(sid);
        sawLifecycle = true;
        pieces.push(await lifecycle());
      }

      const name = String(event?.tool ?? '').toLowerCase();
      if (name === 'grep' || name === 'glob') {
        pieces.push(await cbmAugmentV2({
          hook_event_name: 'PreToolUse',
          tool_name: name === 'grep' ? 'Grep' : 'Glob',
          tool_input: event?.input ?? {},
          cwd: dir,
        }));
      } else if (name === 'read') {
        const args = event?.input ?? {};
        const filePath = args.filePath ?? args.file_path ?? args.path;
        if (typeof filePath === 'string' && filePath) {
          pieces.push(await cbmAugmentV2({
            hook_event_name: 'PostToolUse',
            tool_name: 'Read',
            tool_input: { file_path: filePath },
            cwd: dir,
          }));
        }
      }

      const extra = pieces.filter(Boolean).join('\n');
      if (!extra) return;
      const content = result.content;
      if (typeof content === 'string') {
        event.result = { ...result, content: content + '\n' + extra };
      } else if (Array.isArray(content)) {
        event.result = { ...result, content: [...content, { type: 'text', text: extra }] };
      } else {
        event.result = { ...result, content: extra };
      }
    });

    await ctx.session.hook('compaction', (event) => {
      const sid = event?.sessionID;
      if (typeof sid === 'string') seenSessions.delete(sid);
      else { seenSessions.clear(); sawLifecycle = false; }
    });
  },
};
